def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    elements = [t.get('element') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ[i] for i in range(n) if elements[i] == 'N')
    if total <= 0:
        return 0.0
    degree = [0 for i in range(n)]
    partner = [-1 for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.6:
            if elements[i] == 'N' and elements[j] == 'N' and occ[i] > 0 and occ[j] > 0:
                degree[i] += 1
                partner[i] = j
    value = 0.0
    for i in range(n):
        j = partner[i]
        if elements[i] == 'N' and degree[i] == 1 and 0 <= j < n and j != i:
            if degree[j] == 1 and partner[j] == i:
                value += occ[i]
    return value / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    elements = [t.get('element') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ[i] for i in range(n) if elements[i] == 'N')
    if total <= 0:
        return 0.0
    coordination = [0.0 for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.6:
            if elements[i] == 'N' and elements[j] == 'N':
                coordination[i] += occ[j]
    mean = sum(occ[i] * coordination[i] for i in range(n) if elements[i] == 'N') / total
    return sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n) if elements[i] == 'N') / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    valid = [r is not None and r > 0 for r in radii]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ[i] for i in range(n) if valid[i])
    if total <= 0:
        return 0.0
    coordination = [0.0 for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if valid[i] and valid[j] and d <= 1.25 * (radii[i] + radii[j]):
                coordination[i] += occ[j]
    mean = sum(occ[i] * coordination[i] for i in range(n) if valid[i]) / total
    return sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n) if valid[i]) / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    eneg = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    valid = [radii[i] is not None and radii[i] > 0 and eneg[i] is not None for i in range(n)]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ[i] for i in range(n) if valid[i])
    if total <= 0:
        return 0.0
    field = [0.0 for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if valid[i] and valid[j] and d <= 1.25 * (radii[i] + radii[j]):
                field[i] += occ[j] * (eneg[j] - eneg[i]) / d
    return sum(occ[i] * field[i] ** 2 for i in range(n) if valid[i]) / total
